{
  "name": "@amykit/workflow-setup",
  "version": "0.7.1",
  "description": "Onboarding as an amy workflow: amy setup walks a fresh machine through harness, workflow and channels, one ask at a time.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": {
    "url": "https://github.com/nicolasmelo1/amy/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "packages/workflow-setup"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "dependencies": {
    "@amykit/core": "^0.7.1"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0",
    "@amykit/workflow-testkit": "^0.7.1"
  }
}

import {
  ActionContext,
  Moved,
  Plan,
  WorkflowActionScope,
  actionsOf,
  unitOf,
} from "@amykit/core";
import { fieldOf, parseSetting, recordFieldIn, spelledFlag } from "./asks.js";
import { channelsIn, given, harnessIn, queueOf, workflowIn } from "./answers.js";
import { Effect, stepOf } from "./machine.js";
import { Observation, Policy, Scope } from "./observation.js";
import { green } from "./ports/result.js";
import type { MachineConfig } from "./ports/ConfigFile.js";
import type { Result } from "./ports/result.js";
import type { Answers, Configuring, OpenAsk, SetupRecord, SettingValue } from "./record.js";
import type { configSchema, needs } from "./plugin.js";

type ActionScope = WorkflowActionScope<typeof configSchema, Policy, typeof needs>;
type Work = ActionContext<SetupRecord, Observation>;

/**
 * The actions: each one port call, its result left in the outcomes for the
 * fold to judge. None of them reads a terminal, parses yaml or runs npm —
 * those live behind the ports, so a window conversation can answer this
 * walk unchanged.
 */
export const actions = {
  "read-config": async (scope: ActionScope, work: Work): Promise<void> => {
    work.outcomes["read-config"] = await scope.ports.config.read();
  },

  "write-setup-profile": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "write-setup-profile" }>): Promise<void> => {
    work.outcomes["write-setup-profile"] = await scope.ports.config.writeSetupProfile(effect.workflow);
  },

  install: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "install" }>): Promise<void> => {
    work.outcomes.install = await scope.ports.installer.install(effect.spec);
  },

  "write-ladder": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "write-ladder" }>): Promise<void> => {
    work.outcomes["write-ladder"] = await scope.ports.config.writeLadder(effect.harness);
  },

  setup: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "setup" }>): Promise<void> => {
    work.outcomes.setup = await scope.ports.checks.setup(effect.plugin);
  },

  ping: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "ping" }>): Promise<void> => {
    work.outcomes.ping = await scope.ports.checks.check(effect.plugin);
  },

  "write-workflow": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "write-workflow" }>): Promise<void> => {
    work.outcomes["write-workflow"] = await scope.ports.config.writeWorkflow(effect.name, effect.plugin);
  },

  post: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "post" }>): Promise<void> => {
    const conversation = scope.ports.conversation;
    if (!conversation) throw new Error(`the ${effect.ask.id} ask was posted with no conversation mounted`);
    const thread = await conversation.open(unitOf(work.record), "amy setup");
    const since = scope.ctx.now().toISOString();
    await conversation.post(thread, { text: effect.ask.prompt, ask: effect.ask });
    work.outcomes.post = { thread: thread.id, since };
  },

  "ask-setting": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "ask-setting" }>): Promise<void> => {
    const conversation = scope.ports.conversation;
    if (!conversation) throw new Error(`${effect.plugin}.${effect.field} was asked with no conversation mounted`);
    const thread = await conversation.open(unitOf(work.record), "amy setup");
    const since = scope.ctx.now().toISOString();
    await conversation.post(thread, { text: effect.text });
    work.outcomes["ask-setting"] = { thread: thread.id, since };
  },

  "write-settings": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "write-settings" }>): Promise<void> => {
    work.outcomes["write-settings"] = await scope.ports.config.writeSettings(effect.plugin, effect.values);
  },

  check: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "check" }>): Promise<void> => {
    work.outcomes.check = await scope.ports.checks.check(effect.plugin);
  },

  pending: async (_scope: ActionScope, work: Work, effect: Extract<Effect, { type: "pending" }>): Promise<void> => {
    // Nothing to do — there is no terminal to say it through. The fold
    // keeps the ask and its flag on the record, which is where the host
    // reads them.
    work.outcomes.pending = effect.ask;
  },
};

/**
 * The fold: keeps what each look produced, so the next look judges it.
 *
 * The steps and their results, the answers as they resolve, the ask as it
 * posts and clears, the configuring cursor as it advances — every fold
 * below is idempotent, because a look that is taken again (a wait held, an
 * engine retry) must find the record saying the same thing it said before.
 */
export function remember(
  _scope: Scope,
  current: SetupRecord,
  outcomes: Record<string, unknown>,
  observation: Observation,
  moved: Moved | null,
  decision: Plan,
  _now: Date,
): SetupRecord {
  const plan = decision;
  const effects = actionsOf(plan) as readonly Effect[];
  const next: SetupRecord = { ...current, answers: { ...current.answers } };

  next.steps = foldedSteps(current, effects, outcomes);
  const read = outcomes["read-config"] as Result<MachineConfig> | undefined;
  if (green(read)) next.machine = read.value;

  const answered = foldedAnswers(current, observation);
  if (answered.resolved) next.ask = undefined;
  next.answers = answered.answers;

  const written = foldedWritten(next.answers, effects, outcomes);
  if (written) next.answers = written;

  const setting = answeredSetting(current, observation);
  if (setting.configuring) next.configuring = setting.configuring;
  if (setting.answered) next.ask = undefined;

  const consumedFlags: string[] = [];
  next.configuring = foldCursor(next.configuring ?? current.configuring, next, observation, outcomes, moved, plan, consumedFlags);

  const ask = foldedAsk(effects, outcomes);
  if (ask) next.ask = ask;

  const pending = outcomes.pending as SetupRecord["pending"];
  if (pending) next.pending = pending;

  if (moved?.to === "STOPPED") next.stoppedReason = plan.why;
  next.flags = [...current.flags, ...answered.flags, ...consumedFlags];
  return next;
}

/** The steps this look's port effects produced, keyed by what each was about. */
function foldedSteps(current: SetupRecord, effects: readonly Effect[], outcomes: Record<string, unknown>): Record<string, unknown> {
  const steps: Record<string, unknown> = { ...current.steps };
  for (const effect of effects) {
    const result = outcomes[effect.type];
    if (PORT_STEPS.has(effect.type) && result !== undefined) steps[stepOf(effect)] = result;
  }
  return steps;
}

/**
 * The answers that resolved this look, by a flag before the ask or a reply
 * after it, with the flag spellings the walk consumed. An answer already on
 * the record is not resolved again, so its ask stays cleared and its flag
 * is not consumed twice.
 */
function foldedAnswers(current: SetupRecord, observation: Observation): { answers: Answers; flags: readonly string[]; resolved: boolean } {
  const answers: Answers = { ...current.answers };
  const flags: string[] = [];
  let resolved = false;
  const harness = answers.harness ? undefined : harnessIn(current, observation);
  if (harness) {
    answers.harness = { name: harness.name, plugin: harness.plugin };
    if (harness.via === "flag") flags.push(spelledFlag("harness", harness.name));
    resolved = true;
  }
  const workflow = answers.workflow !== undefined ? undefined : workflowIn(current, observation);
  if (workflow) {
    answers.workflow = workflow.answer;
    if (workflow.via === "flag") flags.push(spelledFlag("workflow", workflow.answer === "none" ? "none" : workflow.answer.name));
    resolved = true;
  }
  const channels = answers.channels ? undefined : channelsIn(current, observation);
  if (channels) {
    answers.channels = channels.choices;
    if (channels.via === "flag" && channels.choices.length > 0) flags.push(spelledFlag("channels", channels.choices.map((choice) => choice.name)));
    resolved = true;
  }
  return { answers, flags, resolved };
}

/** The settings a green write recorded, folded into the answers it wrote for. */
function foldedWritten(answers: Answers, effects: readonly Effect[], outcomes: Record<string, unknown>): Answers | undefined {
  const writeEffect = effects.find((effect): effect is Extract<Effect, { type: "write-settings" }> => effect.type === "write-settings");
  const written = outcomes["write-settings"] as Result<void> | undefined;
  if (green(written) && writeEffect) {
    return { ...answers, settings: { ...answers.settings, [writeEffect.plugin]: writeEffect.values } };
  }
  return undefined;
}

/**
 * The setting answered this very look, folded into the values of the plugin
 * that asked — before the cursor moves, so the answer lands in the plugin
 * whose ask it answered and not in the next one's.
 */
function answeredSetting(current: SetupRecord, observation: Observation): { configuring: Configuring | undefined; answered: boolean } {
  const open = current.ask?.form === "post" ? current.ask : undefined;
  const field = open ? fieldOf(open.id) : undefined;
  if (!open || !field) return { configuring: undefined, answered: false };
  const cursor = current.configuring;
  const plugin = cursor?.plugins[cursor.at];
  const parsed = plugin !== undefined && observation.answer ? replyParsed(current, observation, plugin, field) : undefined;
  if (cursor && parsed !== undefined) {
    return { configuring: { ...cursor, values: { ...cursor.values, [field]: parsed } }, answered: true };
  }
  return { configuring: undefined, answered: false };
}

/** One reply line parsed to its field's type, against what the machine already holds. */
function replyParsed(current: SetupRecord, observation: Observation, plugin: string, field: string): SettingValue | undefined {
  const schema = green(observation.schema) ? observation.schema.value : undefined;
  const spec = schema?.[field];
  if (!spec || !observation.answer) return undefined;
  const held = current.machine?.settings[plugin]?.[field];
  return parseSetting(spec, observation.answer.text, held);
}

/** The ask that posted this look, kept with the marker its replies are read after. */
function foldedAsk(effects: readonly Effect[], outcomes: Record<string, unknown>): OpenAsk | undefined {
  const postEffect = effects.find((effect): effect is Extract<Effect, { type: "post" }> => effect.type === "post");
  if (postEffect && outcomes.post) {
    const posted = outcomes.post as { thread: string; since: string };
    return { id: postEffect.ask.id, form: postEffect.ask.form, thread: posted.thread, since: posted.since };
  }
  const settingEffect = effects.find((effect): effect is Extract<Effect, { type: "ask-setting" }> => effect.type === "ask-setting");
  if (settingEffect && outcomes["ask-setting"]) {
    const asked = outcomes["ask-setting"] as { thread: string; since: string };
    return { id: `${settingEffect.plugin}.${settingEffect.field}`, form: "post", thread: asked.thread, since: asked.since };
  }
  return undefined;
}

/** The effects whose outcome is a step result, judged by the next look. */
const PORT_STEPS = new Set([
  "read-config",
  "write-setup-profile",
  "install",
  "write-ladder",
  "setup",
  "ping",
  "write-workflow",
  "write-settings",
  "check",
]);

/**
 * Where the configuring has got to.
 *
 * The cursor starts the moment the walk enters CONFIGURING with something
 * chosen, and its `at` moves past a plugin when its slice is written green
 * or when its schema refuses it. A flag that answered a setting before its
 * ask was asked is in hand the moment the plugin's turn comes, so the ask
 * is never posted and the flag's spelling is kept.
 *
 * The queue is read from the half-folded record, because the channels
 * answer and the entry into CONFIGURING are folded in the same look — the
 * queue is the answer's.
 */
function foldCursor(
  cursor: Configuring | undefined,
  record: SetupRecord,
  observation: Observation,
  outcomes: Record<string, unknown>,
  moved: Moved | null,
  plan: Plan,
  consumedFlags: string[],
): Configuring | undefined {
  const queue = queueOf(record);
  const seed = (plugin: string | undefined): Readonly<Record<string, SettingValue>> => {
    if (plugin === undefined) return {};
    const values: Record<string, SettingValue> = {};
    for (const [field, value] of Object.entries(given(record).settings[plugin] ?? {})) {
      values[field] = value as SettingValue;
      // The flag answered this field before its ask was asked; its spelling
      // is kept when it is consumed, which is now.
      consumedFlags.push(spelledFlag(`${plugin}.${field}`, value));
    }
    return values;
  };

  if (moved?.to === "CONFIGURING" && queue.length > 0) {
    const plugins = [...queue];
    return { plugins, at: 0, values: seed(plugins[0]), refused: [] };
  }

  if (!cursor) return undefined;
  const inHand = cursor.plugins[cursor.at];
  if (inHand === undefined) return cursor;

  const refusedField = green(observation.schema) ? recordFieldIn(observation.schema.value) : undefined;
  if (refusedField && !refusedAlready(cursor, inHand)) {
    const following = cursor.plugins[cursor.at + 1];
    return {
      ...cursor,
      at: cursor.at + 1,
      values: seed(following),
      refused: [...cursor.refused, { plugin: inHand, field: refusedField }],
    };
  }

  const written = outcomes["write-settings"] as Result<void> | undefined;
  const wrote = (actionsOf(plan) as readonly Effect[]).some((effect) => effect.type === "write-settings");
  if (green(written) && wrote && !refusedAlready(cursor, inHand)) {
    const following = cursor.plugins[cursor.at + 1];
    return { ...cursor, at: cursor.at + 1, values: seed(following) };
  }
  return cursor;
}

/** Whether the cursor already refused this plugin, so a look taken again does not refuse it twice. */
function refusedAlready(cursor: Configuring, plugin: string): boolean {
  return cursor.refused.some((entry) => entry.plugin === plugin);
}

import type { WorkRecord } from "@amykit/core";
import type { ChannelChoice } from "./ports/Catalog.js";
import type { Observation } from "./observation.js";
import type { SetupRecord } from "./record.js";
import { labelOf } from "./asks.js";

/**
 * What the flags gave before their asks were asked, read off the record a
 * caller started. Read defensively: the input was validated against the
 * workflow's input schema when the record was started, but this is the one
 * place the walk reads it, so this is where it says what it accepts.
 */
export interface Given {
  /** The one plugin `amy setup <plugin>` goes straight to configuring. */
  readonly plugin?: string;
  /** The harness the `--harness` flag chose. */
  readonly harness?: string;
  /** The workflow the `--workflow` flag chose, or `none`. */
  readonly workflow?: string;
  /** The channels the `--channels` flag chose, by name. */
  readonly channels?: readonly string[];
  /** The settings the `--<plugin>.<field>` flags gave, by plugin, by field. */
  readonly settings: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
}

/** The flags a caller passed, keyed as the input schema promises. */
export function given(record: WorkRecord): Given {
  const input = record.input as Partial<Given> | undefined;
  const settings = input?.settings;
  return {
    ...(input?.plugin !== undefined ? { plugin: String(input.plugin) } : {}),
    ...(input?.harness !== undefined ? { harness: String(input.harness) } : {}),
    ...(input?.workflow !== undefined ? { workflow: String(input.workflow) } : {}),
    ...(Array.isArray(input?.channels) ? { channels: input.channels.map(String) } : {}),
    settings: typeof settings === "object" && settings !== null && !Array.isArray(settings) ? settings : {},
  };
}

/**
 * The resolvers: where each answer comes from, in the order it can come.
 *
 * An answer already on the record first (idempotent — the fold and the
 * decision read the same one), then the flag that answered before the ask
 * was asked, then the reply that answered the ask the conversation is
 * holding open. A flag that names nothing the catalog offers is not an
 * answer: the ask posts anyway, and the person chooses what the machine
 * can actually mount.
 */
export type Via = "record" | "flag" | "reply";

export function harnessIn(record: SetupRecord, obs: Observation): { via: Via; name: string; plugin: string } | undefined {
  const answered = record.answers.harness;
  if (answered) return { via: "record", ...answered };
  const flagged = given(record).harness;
  if (flagged) {
    const found = obs.harnesses.find((harness) => harness.name === flagged);
    if (found) return { via: "flag", ...found };
  }
  if (record.ask?.id === "harness" && obs.answer?.answer) {
    const chosen = obs.harnesses.find((harness) => harness.name === obs.answer?.answer?.chosen[0]);
    if (chosen) return { via: "reply", ...chosen };
  }
  return undefined;
}

export function workflowIn(record: SetupRecord, obs: Observation): { via: Via; answer: "none" | { name: string; plugin: string } } | undefined {
  const answered = record.answers.workflow;
  if (answered) return { via: "record", answer: answered };
  const flagged = given(record).workflow;
  if (flagged === "none") return { via: "flag", answer: "none" };
  if (flagged) {
    const found = obs.workflows.find((choice) => choice.name === flagged);
    if (found) return { via: "flag", answer: { name: found.name, plugin: found.plugin } };
  }
  if (record.ask?.id === "workflow" && obs.answer?.answer) {
    const chosen = obs.answer.answer.chosen[0];
    if (chosen === "none") return { via: "reply", answer: "none" };
    const found = obs.workflows.find((choice) => choice.name === chosen);
    if (found) return { via: "reply", answer: { name: found.name, plugin: found.plugin } };
  }
  return undefined;
}

/**
 * The channels the person chose: nothing is an answer too, because a
 * machine may want no channels yet, and every chosen label must name a
 * channel the catalog offers or the reply did not answer the ask.
 */
export function channelsIn(record: SetupRecord, obs: Observation): { via: Via; choices: readonly ChannelChoice[] } | undefined {
  const answered = record.answers.channels;
  if (answered) return { via: "record", choices: answered };
  const flagged = given(record).channels;
  if (flagged) {
    const choices = flagged.map((name) => obs.channels.find((channel) => channel.name === name));
    if (choices.every((channel): channel is ChannelChoice => !!channel)) return { via: "flag", choices };
  }
  if (record.ask?.id === "channels" && obs.answer?.answer) {
    const chosen = obs.answer.answer.chosen;
    if (chosen.length === 0) return { via: "reply", choices: [] };
    const choices = chosen.map((label) => obs.channels.find((channel) => labelOf(channel) === label));
    if (choices.every((channel): channel is ChannelChoice => !!channel)) return { via: "reply", choices };
  }
  return undefined;
}

/**
 * The plugins the walk is to configure: the scope's one when a plugin was
 * named, else the channels chosen. Derived, never folded — the answers say
 * it, and the cursor only says how far it has got.
 */
export function queueOf(record: SetupRecord): readonly string[] {
  const scoped = given(record).plugin;
  if (scoped) return [scoped];
  return record.answers.channels?.map((channel) => channel.plugin) ?? [];
}

/** The plugin the configuring has in hand, once it has one. */
export function handOf(record: SetupRecord): string | undefined {
  const cursor = record.configuring;
  return cursor?.plugins[cursor.at];
}

/**
 * The plugin the walk holds at PLUGIN_INSTALLED and PINGED: the scope's
 * one when a plugin was named, else the harness the person chose.
 *
 * Throws when neither, because a record only reaches those states holding
 * one — the harness ask is answered before the walk advances past it, and a
 * scoped record is started with its plugin.
 */
export function pluginInHand(record: SetupRecord): string {
  const scoped = given(record).plugin;
  if (scoped) return scoped;
  const harness = record.answers.harness?.plugin;
  if (harness) return harness;
  throw new Error("the walk holds no plugin: no scope was named and no harness was chosen");
}

import { Ask, ConfigField, ConfigSchema, Reply } from "@amykit/core";
import type { Harness } from "./ports/Harnesses.js";
import type { ChannelChoice, WorkflowChoice } from "./ports/Catalog.js";
import type { OpenAsk, SettingValue } from "./record.js";

/**
 * The asks, the posts and the flags — pure, so the decision that plans one
 * and the fold that records one read a reply the same way.
 *
 * A controlled ask is an Ask on the conversation port; a plugin setting is
 * not one — the Ask type has no free-text form — so it is a plain post
 * answered by an ordinary reply line, parsed to the field's type here.
 */

/** The harness ask: claude, codex and hermes, the ones detected here first. */
export function harnessAsk(harnesses: readonly Harness[], current?: string): Ask {
  // The current one first when the machine has one, then the detected, then
  // the rest: a detected harness is the likeliest answer and the first thing
  // a person should read. The sort is stable, so the catalog's own order
  // survives inside each band.
  const order = [...harnesses].sort((a, b) => rankOf(b, current) - rankOf(a, current));
  return {
    id: "harness",
    prompt: "Which harness should do the work?",
    form: "choice",
    answers: order.map((harness) => harness.name),
  };
}

function rankOf(harness: Harness, current?: string): number {
  if (harness.name === current) return 2;
  return harness.detected ? 1 : 0;
}

/** The workflow ask: the host's workflows and none, the current one first. */
export function workflowAsk(workflows: readonly WorkflowChoice[]): Ask {
  const order = [...workflows].sort((a, b) => Number(b.current) - Number(a.current));
  return {
    id: "workflow",
    prompt: "Which workflow should this machine drive?",
    form: "choice",
    answers: [...order.map((choice) => choice.name), "none"],
  };
}

/** How one channel appears in the channels ask: its name and its kind together. */
export function labelOf(channel: ChannelChoice): string {
  return `${channel.name} (${channel.kind})`;
}

/** The channels ask: one choices ask, conversation and notifier plugins grouped by kind. */
export function channelsAsk(channels: readonly ChannelChoice[]): Ask {
  const order = [...channels].sort((a, b) => (a.kind === b.kind ? 0 : a.kind === "conversation" ? -1 : 1));
  return {
    id: "channels",
    prompt: "Which channels should reach you?",
    form: "choices",
    answers: order.map(labelOf),
  };
}

/**
 * The plain post that asks one setting field, offering the current value as
 * its default: a reply of nothing keeps what the machine already holds.
 */
export function settingsPost(plugin: string, field: string, spec: ConfigField, current: unknown): string {
  const kept = current === undefined ? "" : ` Answer nothing to keep \`${JSON.stringify(current)}\`.`;
  return `What should ${plugin}'s \`${field}\` be? — ${spec.description}${kept}`;
}

/**
 * One reply line parsed to the field's type: a string as it was typed, a
 * number, a boolean, a string[] comma-separated.
 *
 * Nothing back when the line does not say a value of the field's type — an
 * unparsable line is not an answer, and the ask it failed to answer stays
 * open for the person to try again. An empty line answers with the current
 * value when one exists, which is what "offered as its default" means; for
 * a string[] with no current value an empty line is an empty list, the one
 * value an empty line can spell for it.
 */
export function parseSetting(spec: ConfigField, line: string, current: unknown): SettingValue | undefined {
  if (spec.type === "record") return undefined; // never asked: the plugin was refused for it
  const trimmed = line.trim();
  if (trimmed === "") {
    if (holds(spec, current)) return current as SettingValue;
    return spec.type === "string[]" ? [] : undefined;
  }
  switch (spec.type) {
    case "string":
      return line;
    case "number": {
      const asNumber = Number(trimmed);
      return Number.isFinite(asNumber) ? asNumber : undefined;
    }
    case "boolean":
      return trimmed === "true" ? true : trimmed === "false" ? false : undefined;
    case "string[]":
      return trimmed.split(",").map((item) => item.trim()).filter((item) => item !== "");
  }
}

/** Whether a current value is one the field's type accepts, so offering it is honest. */
function holds(spec: ConfigField, current: unknown): boolean {
  switch (spec.type) {
    case "string":
      return typeof current === "string";
    case "number":
      return typeof current === "number" && Number.isFinite(current);
    case "boolean":
      return typeof current === "boolean";
    case "string[]":
      return Array.isArray(current) && current.every((item) => typeof item === "string");
    case "record":
      return false;
  }
}

/** The flag that would answer one ask, spelled as the person would write it. */
export function flagFor(ask: string): string {
  switch (ask) {
    case "harness":
      return "--harness <name>";
    case "workflow":
      return "--workflow <name|none>";
    case "channels":
      return "--channels <a,b>";
    default:
      return `--${ask} <value>`;
  }
}

/** How a flag-given answer was spelled, as the person wrote it. */
export function spelledFlag(id: string, value: unknown): string {
  const text = Array.isArray(value) ? value.join(",") : String(value);
  return `--${id} ${text}`.trimEnd();
}

/** The field a settings ask id names: everything after the plugin. */
export function fieldOf(askId: string): string | undefined {
  const at = askId.indexOf(".");
  return at < 0 ? undefined : askId.slice(at + 1);
}

/**
 * The reply that answers the open ask, when one did.
 *
 * A marked answer answers a controlled ask by naming it; any line after the
 * ask answers a plain post, because a plain post is what a setting field is
 * asked with and a line is all its medium owes it.
 */
export function answerTo(open: OpenAsk, replies: readonly Reply[]): Reply | undefined {
  const after = replies.filter((reply) => reply.at > open.since);
  if (open.form === "post") return after[0];
  return after.find((reply) => reply.answer?.ask === open.id);
}

/** The fields a schema asks, in its own order. */
export function fieldsOf(schema: ConfigSchema): readonly { field: string; spec: ConfigField }[] {
  return Object.entries(schema).map(([field, spec]) => ({ field, spec }));
}

/** The first record field a schema declares, which refuses the plugin that has it. */
export function recordFieldIn(schema: ConfigSchema): string | undefined {
  return fieldsOf(schema).find(({ spec }) => spec.type === "record")?.field;
}

