/** The package that contributes this workflow, which the setup profile names. */
const SETUP_WORKFLOW = "@amykit/workflow-setup";

export type SetupState =
  | "DETECTING"
  | "HARNESS"
  | "PLUGIN_INSTALLED"
  | "PINGED"
  | "WORKFLOW"
  | "CHANNELS"
  | "CONFIGURING"
  | "CHECKED"
  | "DONE"
  | "STOPPED";

/** Every port call the walk can make. Nothing here touches a terminal: the conversation port is how the person is reached. */
export type Effect =
  | { type: "read-config" }
  | { type: "write-setup-profile"; workflow: string }
  | { type: "install"; spec: string }
  | { type: "write-ladder"; harness: string }
  | { type: "setup"; plugin: string }
  | { type: "ping"; plugin: string }
  | { type: "write-workflow"; name: string; plugin: string }
  | { type: "post"; ask: Ask }
  | { type: "ask-setting"; plugin: string; field: string; text: string }
  | { type: "write-settings"; plugin: string; values: Readonly<Record<string, SettingValue>> }
  | { type: "check"; plugin: string }
  | { type: "pending"; ask: PendingAsk };

/** STOPPED, by name, so every stop spells the state the diagram draws. */
const STOPPED: SetupState = "STOPPED";

type Decision = (record: SetupRecord, obs: Observation, policy: Policy) => Plan;

/**
 * One decision per drawn state.
 *
 * Pure on purpose: every branch is a predicate over the record and the
 * observation, so the whole walk can be driven in a test without npm, a
 * filesystem or a terminal. A step's result is judged here the look after
 * the step ran, from the `steps` the fold kept — a refused or failed step
 * stops the walk naming why, and no state ever mistakes an unread config
 * for an empty one.
 */
export const decide = {
  DETECTING: planDetecting,
  HARNESS: planHarness,
  PLUGIN_INSTALLED: planInstalled,
  PINGED: planPinged,
  WORKFLOW: planWorkflow,
  CHANNELS: planChannels,
  CONFIGURING: planConfiguring,
  CHECKED: planChecked,
  DONE: () => settled("the machine is set up, and the walk is over"),
  STOPPED: () => settled("the walk stopped; the record says why"),
} satisfies Record<SetupState, Decision>;

/**
 * DETECTING reads what the machine already says and makes sure the setup
 * profile is mounted, so no ask offers a default the file did not really
 * give and the next `amy setup` mounts where this one did.
 */
function planDetecting(record: SetupRecord, obs: Observation, _policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const read = step(record, "config");
  if (failed(read)) return advance(STOPPED, read.why); // never read as nothing set
  if (!read) return act("read what the machine already says", { type: "read-config" });
  const profile = step<void>(record, "profile");
  if (failed(profile)) return advance(STOPPED, profile.why); // an internal error, not a refusal
  // The profile is written only once this is a walk the machine will answer:
  // with no conversation mounted and no flag having answered anything, the
  // walk stops at its first ask having configured nothing, and a profile
  // written ahead of that would leave a config.yaml no walk earned (A7).
  const engaged =
    obs.asks ||
    harnessIn(record, obs) !== undefined ||
    workflowIn(record, obs) !== undefined ||
    channelsIn(record, obs) !== undefined ||
    given(record).plugin !== undefined;
  if (!profile && engaged) return act("make sure the setup profile is mounted", { type: "write-setup-profile", workflow: SETUP_WORKFLOW });
  return advance("HARNESS", "the machine was read and setup mounts in its own profile");
}

/**
 * HARNESS asks the first question — which harness — installs only the one
 * chosen, and writes its ladder. The ask is never posted when a flag
 * answered it first.
 */
function planHarness(record: SetupRecord, obs: Observation, policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const answered = harnessIn(record, obs);
  if (answered) {
    const install = step<void>(record, `install:${answered.plugin}`);
    if (failed(install)) return advance(STOPPED, install.why);
    if (!install) return act(`install the ${answered.name} harness`, { type: "install", spec: answered.plugin });
    const ladder = step<void>(record, "ladder");
    if (failed(ladder)) return advance(STOPPED, ladder.why);
    if (!ladder) return act(`write the ${answered.name} ladder`, { type: "write-ladder", harness: answered.name });
    return advance("PLUGIN_INSTALLED", `the ${answered.name} harness is installed and its ladder written`);
  }
  return ask(record, obs, policy, harnessAsk(obs.harnesses, currentHarness(record)));
}

/** The harness the machine's ladder already names, when it names one. */
function currentHarness(record: SetupRecord): string | undefined {
  const first = record.machine?.ladder[0];
  return first === undefined ? undefined : first.split(":")[0];
}

/**
 * PLUGIN_INSTALLED runs the installed plugin's setup. A record scoped to
 * one plugin starts here — `amy setup slack` — so it reads the machine and
 * installs its plugin first, then joins the walk this state shares with the
 * harness path. It reads the config here rather than in DETECTING (a state
 * it never entered) and leaves the setup profile alone: the profile is what
 * mounted this walk.
 */
function planInstalled(record: SetupRecord, _obs: Observation, _policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const read = step(record, "config");
  if (!record.machine && failed(read)) return advance(STOPPED, read.why);
  if (!record.machine && !read) return act("read what the machine already says", { type: "read-config" });
  const plugin = pluginInHand(record);
  const install = step<void>(record, `install:${plugin}`);
  if (failed(install)) return advance(STOPPED, install.why);
  if (!install) return act(`install ${plugin}`, { type: "install", spec: plugin });
  const setup = step<readonly CheckFinding[]>(record, `setup:${plugin}`);
  if (failed(setup)) return advance(STOPPED, setup.why);
  if (!setup) return act(`run ${plugin}'s setup`, { type: "setup", plugin });
  const red = setup.value.find((finding) => !finding.ok);
  if (red) return advance(STOPPED, stoppedBy(plugin, red));
  return advance("PINGED", `${plugin} is installed and its setup ran`);
}

/**
 * PINGED waits on the doctor: for a harness, the ping of the models its
 * ladder names. A plugin that is not a harness has no model to ping, and a
 * record scoped to one goes straight on to configuring it — the walk asks
 * no workflow and no channels it was not started for.
 */
function planPinged(record: SetupRecord, obs: Observation, _policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const plugin = pluginInHand(record);
  const scoped = given(record).plugin;
  const harness = obs.harnesses.find((one) => one.plugin === plugin);
  if (!harness) {
    if (!scoped) throw new Error(`PINGED holds ${plugin}, which is no harness the catalog offers`);
    return advance("CONFIGURING", `${plugin} is not a harness, so there is no model to ping`);
  }
  const ping = step<readonly CheckFinding[]>(record, "ping");
  if (failed(ping)) return advance(STOPPED, ping.why);
  if (!ping) return act(`ping the models the ${harness.name} ladder names`, { type: "ping", plugin });
  const red = ping.value.find((finding) => !finding.ok);
  if (red) return advance(STOPPED, stoppedBy(plugin, red));
  return advance("WORKFLOW", `the models the ${harness.name} ladder names answered their ping`);
}

/** WORKFLOW asks which workflow the machine should drive, installs the one chosen, and writes it. */
function planWorkflow(record: SetupRecord, obs: Observation, policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const answered = workflowIn(record, obs);
  if (answered) {
    if (answered.answer === "none") return advance("CHANNELS", "no workflow was wanted");
    const { name, plugin } = answered.answer;
    const install = step<void>(record, `install:${plugin}`);
    if (failed(install)) return advance(STOPPED, install.why);
    if (!install) return act(`install the ${name} workflow`, { type: "install", spec: plugin });
    const written = step<void>(record, "workflow");
    if (failed(written)) return advance(STOPPED, written.why);
    if (!written) return act(`write ${name} as the workflow the machine drives`, { type: "write-workflow", name, plugin });
    return advance("CHANNELS", `the ${name} workflow is installed and written`);
  }
  return ask(record, obs, policy, workflowAsk(obs.workflows));
}

/** CHANNELS asks which channels should reach the person — one choices ask, every kind named in its labels. */
function planChannels(record: SetupRecord, obs: Observation, policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  if (channelsIn(record, obs)) return advance("CONFIGURING", "the channels were chosen");
  return ask(record, obs, policy, channelsAsk(obs.channels));
}

/**
 * CONFIGURING takes the chosen plugins one at a time: install, read its
 * configSchema, ask each field as a plain post with the current value as
 * its default, write the slice, and on to the next.
 *
 * A plugin whose schema has a record field is refused here, naming the
 * field, and no config for it is written — the walk continues with the
 * others, because a schema setup cannot ask is a fact about the plugin, not
 * a reason to stop the machine.
 */
function planConfiguring(record: SetupRecord, obs: Observation, policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const cursor = record.configuring;
  const inHand = cursor?.plugins[cursor.at];
  if (!cursor || !inHand) return advance("CHECKED", "nothing was chosen to be configured");

  const install = step<void>(record, `install:${inHand}`);
  if (failed(install)) return advance(STOPPED, install.why);
  if (!install) return act(`install ${inHand}`, { type: "install", spec: inHand });

  const schema = obs.schema;
  if (failed(schema)) return advance(STOPPED, schema.why);
  if (!schema) throw new Error(`CONFIGURING holds ${inHand}, whose install is green and whose schema was not read`);

  const recordField = recordFieldIn(schema.value);
  if (recordField) return refusedPlan(record, cursor, inHand, recordField);

  const answered = collected(cursor, record, obs, schema.value);
  const field = fieldsOf(schema.value).find(({ field }) => !(field in answered));
  if (field) return askedPlan(record, obs, policy, cursor, inHand, field);

  return writtenPlan(record, obs, cursor, inHand, schema.value);
}

/** A plugin whose schema holds a record field: refused naming it, the walk continues with the rest. */
function refusedPlan(_record: SetupRecord, cursor: Configuring, inHand: string, recordField: string): Plan {
  const next = cursor.plugins[cursor.at + 1];
  return next
    ? act(`refuse ${inHand} for its \`${recordField}\` record field, and install ${next}`, { type: "install", spec: next })
    : advance("CHECKED", `${inHand} was refused for its \`${recordField}\` record field`);
}

/** The ask one unanswered field needs: posted, waited on, or stopped on with the flag that answers it. */
function askedPlan(
  record: SetupRecord,
  obs: Observation,
  policy: Policy,
  cursor: Configuring,
  inHand: string,
  field: { field: string; spec: ConfigField },
): Plan {
  const open = record.ask?.form === "post" ? record.ask : undefined;
  const openField = open ? fieldOf(open.id) : undefined;
  const id = open && openField === field.field ? open.id : `${inHand}.${field.field}`;
  if (!obs.asks) {
    return advance(
      STOPPED,
      `no conversation is mounted to answer ${inHand}'s \`${field.field}\`; ${flagFor(id)} would answer it`,
      { type: "pending", ask: { id, flag: flagFor(id) } },
    );
  }
  if (open && openField === field.field) return wait(policy.askBackoffMs, `waiting for ${inHand}'s \`${field.field}\``);
  return wait(policy.askBackoffMs, `asking ${inHand}'s \`${field.field}\``, {
    type: "ask-setting",
    plugin: inHand,
    field: field.field,
    text: settingsPost(inHand, field.field, field.spec, currentOf(record, inHand, field.field)),
  });
}

/** The settings once every field is answered: written, and on to the next plugin. */
function writtenPlan(record: SetupRecord, obs: Observation, cursor: Configuring, inHand: string, schema: ConfigSchema): Plan {
  const written = step<void>(record, `settings:${inHand}`);
  if (failed(written)) return advance(STOPPED, written.why);
  if (!written) {
    return act(`write ${inHand}'s settings`, {
      type: "write-settings",
      plugin: inHand,
      values: { ...collected(cursor, record, obs, schema) },
    });
  }
  const following = cursor.plugins[cursor.at + 1];
  return following
    ? act(`${inHand} is configured; installing ${following}`, { type: "install", spec: following })
    : advance("CHECKED", "every chosen plugin is configured");
}

/**
 * CHECKED runs the doctor of everything the walk configured — the settings
 * were just written, so this is where a bad token or a wrong target says
 * so. The harness was already pinged; a refused plugin has nothing written
 * to check.
 */
function planChecked(record: SetupRecord, _obs: Observation, _policy: Policy): Plan {
  if (record.stoppedReason) return advance(STOPPED, record.stoppedReason);
  const cursor = record.configuring;
  const refused = new Set((cursor?.refused ?? []).map((entry) => entry.plugin));
  for (const plugin of cursor?.plugins.slice(0, cursor.at) ?? []) {
    if (refused.has(plugin)) continue;
    const check = step<readonly CheckFinding[]>(record, `check:${plugin}`);
    if (failed(check)) return advance(STOPPED, check.why);
    if (!check) return act(`run ${plugin}'s checks`, { type: "check", plugin });
    const red = check.value.find((finding) => !finding.ok);
    if (red) return advance(STOPPED, stoppedBy(plugin, red));
  }
  return advance("DONE", "everything the person chose is installed, configured and checked");
}

/**
 * Posts the ask and waits for it — or stops when no conversation can carry
 * it, recording the ask and the flag that would answer it so the host can
 * print what would get the walk moving again.
 */
function ask(record: SetupRecord, obs: Observation, policy: Policy, toPost: Ask): Plan {
  const id = record.ask?.id ?? toPost.id;
  if (!obs.asks) {
    return advance(STOPPED, `no conversation is mounted to answer the ${id} ask; ${flagFor(id)} would answer it`, {
      type: "pending",
      ask: { id, flag: flagFor(id) },
    });
  }
  if (record.ask) return wait(policy.askBackoffMs, `waiting for the ${id} answer`);
  return wait(policy.askBackoffMs, `asking ${id}`, { type: "post", ask: toPost });
}

/** One step's result off the record; the cast is the caller's, who knows the step's shape. */
function step<T>(record: SetupRecord, key: string): Result<T> | undefined {
  return record.steps?.[key] as Result<T> | undefined;
}

/** The steps key for one person-facing ask: the ask it was about. */
function askStepOf(effect: Extract<Effect, { type: "post" | "ask-setting" }>): string {
  return effect.type === "post" ? `ask:${effect.ask.id}` : `ask:${effect.plugin}.${effect.field}`;
}

/** The steps key for one effect: what it was about, so the next look judges it. */
export function stepOf(effect: Effect): string {
  return (STEP_KEYS[effect.type] as (one: Effect) => string)(effect);
}

/** One key-minter per effect; a missing one is a type error, not a runtime surprise. */
const STEP_KEYS: { readonly [K in Effect["type"]]: (effect: Extract<Effect, { type: K }>) => string } = {
  "read-config": () => "config",
  "write-setup-profile": () => "profile",
  install: (effect) => `install:${effect.spec}`,
  "write-ladder": () => "ladder",
  setup: (effect) => `setup:${effect.plugin}`,
  ping: () => "ping",
  "write-workflow": () => "workflow",
  "write-settings": (effect) => `settings:${effect.plugin}`,
  check: (effect) => `check:${effect.plugin}`,
  post: askStepOf,
  "ask-setting": askStepOf,
  pending: (effect) => `pending:${effect.ask.id}`,
};

/**
 * Why a plugin's red finding stops the walk, naming what it found.
 *
 * The harness doctor's ping names the model that did not answer; anything
 * else a check found names itself. The walk does not invent either — it
 * carries what the check reported.
 */
export function stoppedBy(plugin: string, finding: CheckFinding): string {
  return finding.name === "ping"
    ? `the model ${finding.said} did not answer its ping`
    : `${plugin}'s ${finding.name} check failed: ${finding.said}`;
}

/**
 * The settings gathered for the plugin in hand: what the fold already
 * collected, plus one answered this very look. Pure, so the decision that
 * plans the next post and the fold that keeps the answer agree on what was
 * answered and when.
 */
function collected(
  cursor: NonNullable<SetupRecord["configuring"]>,
  record: SetupRecord,
  obs: Observation,
  schema: ConfigSchema,
): Readonly<Record<string, SettingValue>> {
  const values: Record<string, SettingValue> = parsedFlags(cursor, record, schema);
  const open = record.ask?.form === "post" ? record.ask : undefined;
  const field = open && obs.answer ? fieldOf(open.id) : undefined;
  const spec: ConfigField | undefined = field ? schema[field] : undefined;
  if (open && field && spec && obs.answer) {
    const plugin = cursor.plugins[cursor.at];
    if (plugin !== undefined) {
      const parsed = parseSetting(spec, obs.answer.text, currentOf(record, plugin, field));
      if (parsed !== undefined) values[field] = parsed;
    }
  }
  return values;
}

/**
 * The flag-given values, parsed to their fields' types against the schema
 * in hand (A13). A flag's value arrives as the line the person spelled it
 * as; a line the field's type does not accept, or one naming a field the
 * schema does not declare, is not an answer — the ask it failed to answer
 * stays open, exactly as a reply that did not parse would.
 */
function parsedFlags(
  cursor: NonNullable<SetupRecord["configuring"]>,
  record: SetupRecord,
  schema: ConfigSchema,
): Record<string, SettingValue> {
  const values: Record<string, SettingValue> = { ...cursor.values };
  const inHand = cursor.plugins[cursor.at];
  if (inHand === undefined) return values;
  for (const [flagField, raw] of Object.entries(values)) {
    if (typeof raw !== "string") continue;
    const spec = schema[flagField];
    const parsed = spec ? parseSetting(spec, raw, currentOf(record, inHand, flagField)) : undefined;
    if (parsed === undefined) delete values[flagField];
    else values[flagField] = parsed;
  }
  return values;
}

/** What the machine already holds for one field, for the ask to offer as its default. */
function currentOf(record: SetupRecord, plugin: string, field: string): unknown {
  return record.machine?.settings[plugin]?.[field];
}

/** The plan helper the decisions use for `act`, narrowed to this workflow's effects. */
function act(why: string, effect: Effect): Plan {
  return { kind: "act", effects: [effect], why };
}

import { ConfigSchema, Conversation, Reply, WorkflowPieceContext } from "@amykit/core";
import { answerTo } from "./asks.js";
import { green } from "./ports/result.js";
import type { Harness } from "./ports/Harnesses.js";
import type { ChannelChoice, WorkflowChoice } from "./ports/Catalog.js";
import { Result } from "./ports/result.js";
import type { SetupRecord } from "./record.js";
import { handOf } from "./answers.js";
import type { configSchema, needs } from "./plugin.js";

/** What the declaration hands every piece: the mounted ports, the settings and the policy. */
export type Scope = WorkflowPieceContext<typeof configSchema, Policy, typeof needs>;

/**
 * A snapshot of the world for one look, gathered before deciding.
 *
 * The decision function reads nothing else, so a test can put the machine
 * in any situation by building one of these. The conversation's reply is
 * reduced to the one that answers the open ask, and a plugin's schema is
 * only read once its install is green — a schema read for a package that is
 * not there is a refusal no walk can act on.
 */
export interface Observation {
  now: Date;
  /** Whether a conversation adapter is mounted: the terminal, or a channel like Slack. */
  readonly asks: boolean;
  /** Every harness the catalog knows, the ones detected here marked. */
  readonly harnesses: readonly Harness[];
  /** The workflows the host offers, the current one first. */
  readonly workflows: readonly WorkflowChoice[];
  /** The channel plugins, conversation and notifier. */
  readonly channels: readonly ChannelChoice[];
  /** The reply that answers the open ask, when one is open and a person answered it. */
  readonly answer: Reply | undefined;
  /** The configSchema of the plugin being configured, once its install is green. */
  readonly schema: Result<ConfigSchema> | undefined;
}

/** The defaults every policy key reads, so a decision reading one is honest about it. */
export interface Policy {
  /**
   * How long the walk waits between looks at an ask the person has not
   * answered. Setup asks a person, not a machine, and a person answers in
   * their own time.
   */
  askBackoffMs: number;
}

export const DEFAULT_POLICY: Policy = { askBackoffMs: 30_000 };

/**
 * Gathers what the current look can see.
 *
 * Every state gets the same snapshot: setup runs once, and the price of a
 * look is a few port calls — cheaper than a decision that reads a world it
 * was not built for.
 */
export async function observe(scope: Scope, current: SetupRecord): Promise<Observation> {
  const conversation: Conversation | undefined = scope.ports.conversation;
  const [harnesses, workflows, channels] = await Promise.all([
    scope.ports.harnesses.all(),
    scope.ports.catalog.workflows(),
    scope.ports.catalog.channels(),
  ]);
  const replies =
    current.ask && conversation ? await conversation.replies({ id: current.ask.thread }, current.ask.since) : [];
  const inHand = handOf(current);
  const schema =
    inHand && green(current.steps?.[`install:${inHand}`] as Result<void> | undefined)
      ? await scope.ports.config.schemaOf(inHand)
      : undefined;
  return {
    now: scope.ctx.now(),
    asks: conversation !== undefined,
    harnesses,
    workflows,
    channels,
    answer: current.ask ? answerTo(current.ask, replies) : undefined,
    schema,
  };
}

import { ConfigSchema, Conversation, defineWorkflow, optional, port } from "@amykit/core";
import { decide } from "./machine.js";
import { DEFAULT_POLICY, observe } from "./observation.js";
import { actions, remember } from "./actions.js";

/**
 * The walk's actions, minus the two that reach the person, when nobody can
 * answer them: a mount with no conversation stops on its first ask and
 * never posts, so declaring `post` there would demand a port the machine
 * chose not to mount. The stopped ask is still recorded — `pending` is
 * bookkeeping, not person-facing.
 */
const actionsFor = (mounted: Conversation | undefined) => {
  if (mounted) return actions;
  const silent = { ...actions } as Partial<typeof actions>;
  delete silent.post;
  delete silent["ask-setting"];
  return silent;
};
import { Catalog } from "./ports/Catalog.js";
import { Checks } from "./ports/Checks.js";
import { ConfigFile } from "./ports/ConfigFile.js";
import { Harnesses } from "./ports/Harnesses.js";
import { Installer } from "./ports/Installer.js";

export const configSchema = {
  "policy.askBackoffMs": {
    type: "number",
    default: 30_000,
    description: "how long the walk waits between looks at an ask the person has not answered",
  },
} satisfies ConfigSchema;

/**
 * The answers `amy setup` passes as flags, each of which answers its ask
 * before it is asked. Nothing here is required: a record started with none
 * asks every question, and one started with all of them writes without
 * posting anything.
 */
export const inputSchema = {
  plugin: {
    type: "string",
    description: "the one plugin `amy setup <plugin>` goes straight to configuring, as the host resolved it",
  },
  harness: { type: "string", description: "the harness the --harness flag chose" },
  workflow: { type: "string", description: "the workflow the --workflow flag chose, or none" },
  channels: { type: "string[]", description: "the channels the --channels flag chose, by name" },
  settings: {
    type: "record",
    description: "the settings the --<plugin>.<field> flags gave, by plugin, by field, inside the shared accepted set",
  },
} satisfies ConfigSchema;

/**
 * Every service the walk reaches for, behind a port.
 *
 * The host owns npm, config.yaml, the harnesses' home directories and the
 * terminal; this package owns the walk. The conversation is optional on
 * purpose: a machine with nothing mounted to answer an ask is one the walk
 * must stop on rather than post into the void.
 */
export const needs = {
  harnesses: port<Harnesses>(),
  catalog: port<Catalog>(),
  installer: port<Installer>(),
  config: port<ConfigFile>(),
  checks: port<Checks>(),
  conversation: optional<Conversation>(),
};

/**
 * Setup is a workflow like any other: drawn in workflow.mmd, mounted with
 * ports, kept by the store as any record is. It differs from the others
 * only in depending on the person's input at some steps, and in running
 * once — `amy setup` is the event that starts one record.
 */
export const plugin = defineWorkflow({
  name: "setup",
  pluginName: "@amykit/workflow-setup",
  configSchema,
  input: inputSchema,
  policy: DEFAULT_POLICY,
  needs,
  decide,
  record: () => ({ answers: { settings: {} }, flags: [] }),
  observe,
  actions: (scope) => actionsFor(scope.ports.conversation),
  remember,
});

/**
 * One workflow the host offers to drive, as the ask reads it.
 */
export interface WorkflowChoice {
  /** The name the ask offers. */
  readonly name: string;
  /** The package that contributes the workflow. */
  readonly plugin: string;
  /** Whether the machine already drives it, so the ask offers it first. */
  readonly current: boolean;
}

/**
 * One channel plugin the catalog offers: how the machine reaches the person.
 *
 * The kind travels into the ask's answer labels, so the person chooses
 * between a conversation and a notifier knowing which is which.
 */
export interface ChannelChoice {
  /** The name the ask offers. */
  readonly name: string;
  /** The package that mounts it. */
  readonly plugin: string;
  readonly kind: "conversation" | "notifier";
}

/**
 * What the host offers the walk to choose from.
 *
 * Plain listings, not results: the host is up — setup is running on it — so
 * what it offers is a fact, and a host that cannot say is a host that cannot
 * mount the walk either.
 */
export interface Catalog {
  /** The workflows this machine could drive, the current one first. */
  workflows(): Promise<readonly WorkflowChoice[]>;
  /** The channel plugins, conversation and notifier, in the catalog's order. */
  channels(): Promise<readonly ChannelChoice[]>;
}

import { Result } from "./result.js";

/**
 * One thing a plugin's doctor found, green or red.
 *
 * A harness's doctor pings the models it was given, and its ping finding is
 * named `ping` with the model that did not answer as what it said — that is
 * the finding that stops the walk naming the model.
 */
export interface CheckFinding {
  /** The check's name, e.g. `ping`. */
  readonly name: string;
  readonly ok: boolean;
  /** What the check said: the model that answered, or the one that did not. */
  readonly said: string;
}

/**
 * Runs a plugin's setup and its doctor-shaped checks.
 *
 * The walk never pings anything itself: the port carries whatever the
 * plugin's own checks report, and a red finding stops the walk naming what
 * the finding said.
 */
export interface Checks {
  /**
   * Prepares what the plugin owns outside amy's state, answering the way a
   * check does.
   */
  setup(plugin: string): Promise<Result<readonly CheckFinding[]>>;
  /** The plugin's doctor: for a harness, the ping of the models it was given. */
  check(plugin: string): Promise<Result<readonly CheckFinding[]>>;
}

import { ConfigSchema } from "@amykit/core";
import { Result } from "./result.js";

/**
 * What the machine already says, read once at the start of the walk.
 *
 * This is what each ask offers as its default: a machine already set up
 * answers its own questions first, and the person edits rather than starts
 * over. The ladder is read as written because the ping that follows an
 * install is of the models the ladder names — the walk does not invent them.
 */
export interface MachineConfig {
  /** The harness ladder, as written: entries like `codex:gpt-5`, cheapest first. */
  readonly ladder: readonly string[];
  /** The workflow the machine drives, empty when none. */
  readonly workflow: string;
  /** One settings slice per installed plugin, keyed by package name. */
  readonly settings: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
}

/**
 * The machine's config.yaml, which the walk reads and writes only through
 * here. No step of the walk parses yaml, merges blocks or spells a file
 * path: the adapter owns the file's words, and every answer it gives is one
 * of the three a result can be — a file that does not parse is never read as
 * nothing set.
 */
export interface ConfigFile {
  /**
   * The current defaults and ladder.
   *
   * Refused, naming the file and the parser's first error, when the file
   * does not parse or cannot be read; internal when the read failed rather
   * than the file.
   */
  read(): Promise<Result<MachineConfig>>;
  /**
   * Writes the setup profile block: the profile `amy setup` mounts in,
   * naming this workflow. Run every time, leaving what an earlier run made
   * alone.
   */
  writeSetupProfile(workflow: string): Promise<Result<void>>;
  /** Writes the ladder for the harness the person chose. */
  writeLadder(harness: string): Promise<Result<void>>;
  /** Writes the workflow the person chose as the one the machine drives. */
  writeWorkflow(name: string, plugin: string): Promise<Result<void>>;
  /**
   * One plugin's configSchema, the closed five-type format it declares.
   *
   * Refused, naming the plugin, when it is not installed or mounts nothing
   * amy can read.
   */
  schemaOf(plugin: string): Promise<Result<ConfigSchema>>;
  /**
   * Writes one plugin's settings slice with the answers the person gave.
   *
   * A merge, never a rewrite of the whole slice: a re-run must not
   * overwrite a value the person did not answer anew.
   */
  writeSettings(plugin: string, values: Readonly<Record<string, unknown>>): Promise<Result<void>>;
}

/**
 * One harness this machine could run, and whether it is here.
 *
 * A harness is detected by its own home directory, not by a binary on PATH:
 * the directory is what its skills and its login live under, and a binary
 * without them is not a harness amy can drive.
 */
export interface Harness {
  /** The name the asks offer: claude, codex, hermes. */
  readonly name: string;
  /** The package that mounts it. */
  readonly plugin: string;
  /** Whether its home directory is on this machine. */
  readonly detected: boolean;
}

/**
 * The harnesses this machine could run.
 *
 * The whole listing rather than only the detected ones, because the ask
 * offers every harness with the detected ones first — a machine without the
 * harness the person uses is exactly the one that must still be able to
 * name it.
 */
export interface Harnesses {
  /** Every harness amy knows, the ones detected here marked. */
  all(): Promise<readonly Harness[]>;
}

import { Result } from "./result.js";

/**
 * Installs a package the person chose.
 *
 * Only what the person chose ever goes through here, which is what the
 * guarantee "only the harness, workflow and plugins the person chose are
 * installed" is made of. Installing a package that is already installed is
 * green, not a refusal: `amy setup slack` on a machine that has slack must
 * go on to configure it, not stop to say it is there.
 */
export interface Installer {
  /**
   * Installs one package spec.
   *
   * Refused when npm says no, naming the package and npm's first error
   * line; internal when the install could not even be attempted.
   */
  install(spec: string): Promise<Result<void>>;
}

/**
 * The three ways anything this workflow asks of the host can come out.
 *
 * Success is green and carries what was asked for; a refusal is the host
 * saying no with the reason; an internal error is the host failing. What is
 * deliberately not here is "nothing was set": a config.yaml that cannot be
 * read refuses by name rather than reading as an empty machine, so nothing
 * ever reads green unread.
 */
export type Result<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly kind: "refused"; readonly why: string }
  | { readonly ok: false; readonly kind: "internal"; readonly why: string };

/** A green answer, carrying what was asked for. */
export function ok<T>(value: T): Result<T> {
  return { ok: true, value };
}

/** The host saying no, with the reason it said so. */
export function refused<T>(why: string): Result<T> {
  return { ok: false, kind: "refused", why };
}

/** The host failing, with what failed. */
export function internal<T>(why: string): Result<T> {
  return { ok: false, kind: "internal", why };
}

/** Whether a result is green, narrowed so a decision can read its value. */
export function green<T>(result: Result<T> | undefined): result is { ok: true; value: T } {
  return !!result && result.ok;
}

/** Whether a step came out refused or failed, narrowed so its reason can be read. */
export function failed<T>(result: Result<T> | undefined): result is Extract<Result<T>, { ok: false }> {
  return !!result && !result.ok;
}

import { Ask, WorkRecord } from "@amykit/core";
import type { ChannelChoice } from "./ports/Catalog.js";
import type { MachineConfig } from "./ports/ConfigFile.js";
import type { SetupState } from "./machine.js";

/**
 * One setting value as the shared accepted set spells it: the four types a
 * flag or a reply line can carry. A record field is not one of them — a
 * plugin whose schema has one is refused, not asked.
 */
export type SettingValue = string | number | boolean | readonly string[];

/** The plugin the person chose, as the ask read it. */
export interface ChosenHarness {
  readonly name: string;
  readonly plugin: string;
}

/** The workflow the person chose, or none. */
export type ChosenWorkflow = "none" | { readonly name: string; readonly plugin: string };

/**
 * The answers the walk has been given: by a flag before its ask was asked,
 * or by the person after it. Kept on the record rather than re-read from the
 * conversation, so a look that moves on an answer is a look that can say
 * what the answer was.
 */
export interface Answers {
  /** The harness chosen. */
  harness?: ChosenHarness;
  /** The workflow chosen, or `none`. */
  workflow?: ChosenWorkflow;
  /** The channels chosen, in the order they were answered. */
  channels?: readonly ChannelChoice[];
  /** The settings written, one slice per configured plugin. */
  readonly settings: Readonly<Record<string, Readonly<Record<string, SettingValue>>>>;
}

/**
 * The ask the walk has posted and not yet had answered.
 *
 * One ask is open at a time: setup asks one question at a time. `since` is
 * the marker replies are read after, so a look never mistakes the answer to
 * an earlier ask for the answer to this one.
 */
export interface OpenAsk {
  /** `harness`, `workflow`, `channels`, or `<plugin>.<field>` for a settings post. */
  readonly id: string;
  /** The ask's own form, or `post` for the plain post a setting field is asked with. */
  readonly form: Ask["form"] | "post";
  /** The thread the ask was posted to, and the marker replies are read after. */
  readonly thread: string;
  readonly since: string;
}

/**
 * One ask the walk stopped on, unanswered: what it was, and the flag that
 * would answer it. Recorded so the host can print the `amy setup` flags
 * that would get the walk moving again, with no terminal of its own to say
 * them through.
 */
export interface PendingAsk {
  readonly id: string;
  /** The flag that would answer it, spelled as the person would write it. */
  readonly flag: string;
}

/**
 * Where the walk has got to configuring the plugins the person chose.
 *
 * The cursor is progress, not plan: which plugins are left is derivable from
 * the answers, but which one is in hand and how far its fields have been
 * asked is what happened, and only the fold knows.
 */
export interface Configuring {
  /** The plugins chosen, in the order they were answered; `at` is in hand. */
  readonly plugins: readonly string[];
  /** Which one is in hand. Those before it are written, or refused. */
  readonly at: number;
  /** The answers collected for the one in hand, by field. */
  readonly values: Readonly<Record<string, SettingValue>>;
  /** The plugins refused for a record field, each naming the field. */
  readonly refused: readonly { readonly plugin: string; readonly field: string }[];
}

/**
 * Everything the walk remembers about one run of setup, between looks.
 *
 * The steps the walk took and how they came out are keyed by what each was
 * about (`install:<package>`, `ladder`, `settings:<plugin>` …), so the look
 * after a step judges it: a green key moves the walk on, a refused or failed
 * one stops it naming why. Nothing is ever inferred from an absent key.
 */
export interface SetupRecord extends WorkRecord {
  state: SetupState;
  /** What the machine already said, once read: the defaults each ask offers. */
  machine?: MachineConfig;
  /** Each step the walk has taken and how it came out, keyed by what it was about. */
  steps?: Readonly<Record<string, unknown>>;
  /** The ask posted and not yet answered. */
  ask?: OpenAsk;
  /** The ask the walk stopped on, unanswered, when it stopped on one. */
  pending?: PendingAsk;
  /** The answers the walk has been given. */
  answers: Answers;
  /** The flag spellings the walk consumed, as the person wrote them. */
  flags: readonly string[];
  /** Why the walk stopped, when it has: what the failures name. */
  stoppedReason?: string;
  /** Where the configuring has got to, once something was chosen to configure. */
  configuring?: Configuring;
}
